window.loadLatestPatrolPointFast = function(sessionId, staff){

  const run = async function(){

    try {

      sessionId =
        String(sessionId || "").trim();

      if(
        !sessionId ||
        !staff ||
        !window.fb ||
        !window.db
      ){
        return;
      }

      const {
        collection: collFb,
        query: queryFb,
        orderBy: orderByFb,
        limit: limitFb,
        getDocs: getDocsFb
      } = window.fb;

      if(
        typeof collFb !== "function" ||
        typeof queryFb !== "function" ||
        typeof orderByFb !== "function" ||
        typeof getDocsFb !== "function"
      ){
        console.warn(
          "⚠ Latest patrol fast path unavailable:",
          sessionId
        );
        return;
      }

      const pointsCollection =
        collFb(
          window.db,
          "patrol_tracks",
          sessionId,
          "points"
        );

      const queryParts = [
        orderByFb("time", "desc")
      ];

      // Use limit(1) when the Firebase wrapper exposes it.
      // If unavailable, the query still works with orderBy()
      // and the first document is used below.
      if(typeof limitFb !== "function") return;
      if(typeof limitFb === "function"){
        queryParts.push(limitFb(1));
      }

      const latestPointQuery =
        queryFb(
          pointsCollection,
          ...queryParts
        );

      // This is deliberately not awaited by the caller.
      const pointSnap =
        await getDocsFb(latestPointQuery);

      if(
        !pointSnap ||
        pointSnap.empty ||
        !pointSnap.docs ||
        !pointSnap.docs.length
      ){
        return;
      }

      const pointDoc =
        pointSnap.docs[0];

      const rawPoint =
        typeof pointDoc.data === "function"
          ? pointDoc.data()
          : null;

      if(!rawPoint){
        return;
      }

      const point = {
        ...rawPoint,

        id:
          String(
            rawPoint.id ||
            rawPoint.pointId ||
            pointDoc.id ||
            ""
          ).trim(),

        sessionId:
          String(
            rawPoint.sessionId ||
            sessionId
          ).trim()
      };

      const lat =
        Number(point.lat);

      const lon =
        Number(point.lon);

      if(
        !Number.isFinite(lat) ||
        !Number.isFinite(lon) ||
        lat === 0 ||
        lon === 0
      ){
        return;
      }

      // Ensure the existing marker path can find this point
      // through its authoritative cache helper.
      const current = window.visibleStaffCache?.[cleanName(staff.cleanName || staff.name || '')];
      if (current?.dutyActive !== true || String(current.sessionId || '').trim() !== sessionId ||
          String(point.sessionId || '').trim() !== sessionId) return;
      window.sessionPointCache ??=
        Object.create(null);

      window.sessionPointCache[sessionId] ??=
        Object.create(null);

      const existing = Object.prototype.hasOwnProperty.call(window.sessionPointCache[sessionId], point.id);
      const cached = window.sessionPointCache[sessionId][point.id];
      if (!cached || getPointTime(point) >= getPointTime(cached)) {
        window.sessionPointCache[sessionId][point.id] = point;
        window.StaffRendering?.changed(sessionId, point.id, point, existing, false);
      }

      window.latestPatrolPointByStaff ??=
        Object.create(null);

      const staffName =
        cleanName(
          staff.cleanName ||
          staff.name ||
          ""
        );

      if(!staffName){
        return;
      }

      // Render immediately using the existing authorization
      // and marker-rendering function.
      if(
        typeof window.updateLiveMarkerFromPatrolPoint ===
        "function"
      ){
        window.updateLiveMarkerFromPatrolPoint(
          current,
          point,
          sessionId
        );
      }

      console.log(
        "⚡ LATEST PATROL POINT FAST RENDERED:",
        {
          sessionId,
          staffName,
          pointId: point.id,
          lat,
          lon
        }
      );

    } catch(error){

      // Fast-path failure must never interrupt the normal
      // central listener or the live_staff processing flow.
      console.warn(
        "⚠ Latest patrol point fast path failed:",
        sessionId,
        error
      );

    }

    finally { window.StaffRendering?.finishFast(sessionId, staff); }
  };

  // Start independently. The caller never waits for this.
  Promise.resolve()
    .then(run)
    .catch(error => {
      console.warn(
        "⚠ Latest patrol fast path unhandled failure:",
        sessionId,
        error
      );
    });

  return true;
};

