window.loadLatestPatrolPointFast = function(sessionId, staff){
  const run = async function(){
    const diagnostic = window.StaffStartupDiagnostics;
    try {
      sessionId = String(sessionId || "").trim();
      const {collection, query, orderBy, limit, getDocs} = window.fb || {};
      if (!sessionId || !staff || !window.db ||
          [collection, query, orderBy, limit, getDocs].some(fn => typeof fn !== "function")) return;
      const started = diagnostic?.now();
      const pointSnap = await getDocs(query(
        collection(window.db, "patrol_tracks", sessionId, "points"), orderBy("time", "desc"), limit(8)
      ));
      diagnostic?.snapshot(sessionId, pointSnap, 'fast');
      diagnostic?.record(sessionId, {fastQueryWaitMs: diagnostic.now() - started});
      const current = window.visibleStaffCache?.[cleanName(staff.cleanName || staff.name || '')];
      if (current?.dutyActive !== true || String(current.sessionId || '').trim() !== sessionId ||
          !window.patrolSessionListeners[sessionId]) return;
      const indexedAt = diagnostic?.now();
      const point = window.StaffRendering.selectFast(pointSnap?.docs || [], sessionId);
      diagnostic?.record(sessionId, {fastIndexMs: diagnostic.now() - indexedAt, fastValidPoint: !!point});
      // Invalid recent fixes never authorize a fabricated position. Full history remains the fallback.
      if (!point) return;
      window.sessionPointCache ??= Object.create(null);
      const cache = window.sessionPointCache[sessionId] ??= Object.create(null);
      const existed = Object.prototype.hasOwnProperty.call(cache, point.id), cached = cache[point.id];
      if (!cached || getPointTime(point) >= getPointTime(cached)) {
        cache[point.id] = point;
        window.StaffRendering.changed(sessionId, point.id, point, existed, false);
      }
      window.updateLiveMarkerFromPatrolPoint(current, point, sessionId);
    } catch(error) {
      window.StaffStartupDiagnostics?.record(sessionId, {fastError: String(error.code || error.message)});
      console.warn("⚠ Latest patrol point fast path failed; full history remains active:", sessionId, error);
    } finally { window.StaffRendering?.finishFast(sessionId, staff); }
  };
  Promise.resolve().then(run);
  return true;
};

